        {
            var kit = Tests.LoadAsset<Kit>("kit_metabolism.json");
            var design = kit.Designs.First(d => d.Name == "Nakagin Capsule Tower" && d.Parent == null);
            var result = Kit.ExportDesignModel(kit, design.Guid, ".gltf");
